<div class="container portal-shell">
    <div class="portal-topline"><span>SerendibBank service workspace</span><form method="post" action="/logout"><input type="hidden" name="_csrf" value="<?= $escape($data['csrfToken']) ?>"><button class="text-button" type="submit">Sign out →</button></form></div>
    <section class="portal-header"><div><span class="eyebrow">Service workspace</span><h1>Good morning, <?= $escape($data['name']) ?>.</h1><p>Review customer requests and keep each case moving.</p></div></section>
    <?php if (!empty($data['flash'])): ?><div class="form-success" role="status"><?= $escape($data['flash']) ?></div><?php endif; ?>
    <section class="portal-section" aria-labelledby="staff-applications"><div class="portal-section-heading"><div><span class="eyebrow">Customer requests</span><h2 id="staff-applications">Applications</h2></div><span class="status-pill"><?= count($data['applications']) ?> recent</span></div><div class="staff-list">
        <?php foreach ($data['applications'] as $application): ?><article class="staff-item"><div class="staff-item-main"><span class="request-status"><?= $escape(ucfirst($application['status'])) ?></span><h3><?= $escape($application['product']) ?></h3><p><?= $escape($application['customer_name']) ?> · <?= $escape(ucfirst($application['kind'])) ?> · <?= $escape(substr((string) $application['created_at'], 0, 10)) ?></p><?php if ($application['linked_account_number']): ?><p>Linked account: •••• <?= $escape(substr((string) $application['linked_account_number'], -4)) ?></p><?php endif; ?><?php if ($application['employment_status']): ?><p>Employment: <?= $escape(ucfirst(str_replace('-', ' ', $application['employment_status']))) ?> · Monthly income: LKR <?= $escape($application['monthly_income']) ?></p><?php endif; ?><?php if ($application['notes']): ?><p class="staff-message"><?= nl2br($escape($application['notes'])) ?></p><?php endif; ?></div><?php if ($application['status'] === 'pending'): ?><form method="post" action="/staff/applications/review"><input type="hidden" name="_csrf" value="<?= $escape($data['csrfToken']) ?>"><input type="hidden" name="id" value="<?= $escape($application['id']) ?>"><button class="button" type="submit">Mark reviewed</button></form><?php endif; ?></article><?php endforeach; ?>
        <?php if ($data['applications'] === []): ?><p class="staff-empty">No applications yet.</p><?php endif; ?>
    </div></section>
    <section class="portal-section" aria-labelledby="staff-support"><div class="portal-section-heading"><div><span class="eyebrow">Customer care</span><h2 id="staff-support">Support requests</h2></div><span class="status-pill"><?= count($data['supportRequests']) ?> recent</span></div><div class="staff-list">
        <?php foreach ($data['supportRequests'] as $request): ?><article class="staff-item"><div class="staff-item-main"><span class="request-status"><?= $escape(ucfirst($request['status'])) ?></span><h3><?= $escape($request['subject']) ?></h3><p><?= $escape($request['customer_name']) ?> · <?= $escape(ucfirst($request['category'])) ?> · <?= $escape(substr((string) $request['created_at'], 0, 10)) ?></p><p class="staff-message"><?= $data['labMode'] && $request['subject'] === 'Conversation with digital assistant' ? nl2br((string) $request['message']) : nl2br($escape($request['message'])) ?></p></div><?php if ($request['status'] === 'open'): ?><form method="post" action="/staff/support/resolve"><input type="hidden" name="_csrf" value="<?= $escape($data['csrfToken']) ?>"><input type="hidden" name="id" value="<?= $escape($request['id']) ?>"><button class="button" type="submit">Mark resolved</button></form><?php endif; ?></article><?php endforeach; ?>
        <?php if ($data['supportRequests'] === []): ?><p class="staff-empty">No support requests yet.</p><?php endif; ?>
    </div></section>
</div>
